const biology='La célula es la unidad estructural y funcional de los seres vivos. Las células procariotas no tienen un núcleo delimitado por una membrana. Las células eucariotas sí tienen un núcleo, donde se encuentra el ADN.\n\nLa membrana plasmática regula el intercambio de sustancias entre el interior y el exterior de la célula. El citoplasma contiene los orgánulos y es donde ocurren muchas reacciones químicas.\n\nLas mitocondrias producen ATP mediante la respiración celular. Los ribosomas sintetizan proteínas. El aparato de Golgi modifica, clasifica y empaqueta proteínas. El retículo endoplasmático rugoso tiene ribosomas y participa en la síntesis de proteínas.\n\nLas células vegetales tienen pared celular, una gran vacuola central y cloroplastos. Los cloroplastos realizan la fotosíntesis: transforman la energía luminosa en energía química.';
const history='La Revolución francesa comenzó en 1789, en un contexto de crisis económica, desigualdad social y difusión de las ideas de la Ilustración. La sociedad del Antiguo Régimen estaba dividida en tres estamentos: clero, nobleza y tercer estado.\n\nLa toma de la Bastilla ocurrió el 14 de julio de 1789 y se convirtió en un símbolo del fin del absolutismo. La Declaración de los Derechos del Hombre y del Ciudadano proclamó la libertad y la igualdad ante la ley.\n\nLa monarquía fue abolida en 1792 y se proclamó la República. El período del Terror se desarrolló entre 1793 y 1794. En 1799, Napoleón Bonaparte dio el golpe de Estado del 18 de brumario.';
function initial(){let t=now();return {version:1,settings:{name:'Mi espacio',mode:'ai'},sessions:[],items:[
{id:'sample-bio',type:'note',title:'La célula y sus orgánulos',subject:'Biología',text:biology,created:t,sample:true,favorite:false},
{id:'sample-deck',type:'deck',title:'Biología celular: lo esencial',subject:'Biología',sourceId:'sample-bio',cards:[{q:'¿Cuál es la unidad estructural y funcional de los seres vivos?',a:'La célula.'},{q:'¿Qué diferencia principal hay entre procariotas y eucariotas?',a:'Las procariotas no tienen un núcleo delimitado por una membrana; las eucariotas sí.'},{q:'¿Qué función cumple la membrana plasmática?',a:'Regula el intercambio de sustancias entre el interior y el exterior de la célula.'},{q:'¿Qué producen las mitocondrias?',a:'ATP mediante la respiración celular.'},{q:'¿Cuál es la función de los ribosomas?',a:'Sintetizan proteínas.'},{q:'¿Qué orgánulo realiza la fotosíntesis?',a:'Los cloroplastos, presentes en las células vegetales.'}],created:t,sample:true,favorite:false},
{id:'sample-podcast',type:'podcast',title:'Un viaje al interior de la célula',subject:'Biología',sourceId:'sample-bio',text:'Ana: Bienvenido a Studium. Hoy vamos a visitar un mundo diminuto: el interior de una célula.\n\nLeo: Empecemos por lo básico. ¿Por qué la célula es tan importante?\n\nAna: Porque es la unidad estructural y funcional de los seres vivos. Imagina que cada célula es una pequeña ciudad. Su frontera es la membrana plasmática, que regula lo que entra y sale.\n\nLeo: ¿Y dónde se guardan las instrucciones de esa ciudad?\n\nAna: En las células eucariotas, el ADN se encuentra en el núcleo. Las procariotas, en cambio, no tienen un núcleo rodeado por una membrana.\n\nLeo: Una ciudad también necesita energía.\n\nAna: Exacto. Las mitocondrias producen ATP mediante la respiración celular. Los ribosomas fabrican proteínas, y el aparato de Golgi las modifica, clasifica y empaqueta.\n\nLeo: ¿Qué cambia en una célula vegetal?\n\nAna: Tiene pared celular, una gran vacuola central y cloroplastos. En los cloroplastos se realiza la fotosíntesis, que transforma energía luminosa en energía química.\n\nLeo: Para terminar, recuerda estas tres ideas: membrana para regular, núcleo para el ADN y mitocondrias para producir ATP.\n\nAna: Y ahora, prueba las tarjetas de Biología celular para comprobar lo que has aprendido. ¡Hasta el próximo repaso!',created:t,sample:true,favorite:false},
{id:'sample-history',type:'note',title:'La Revolución francesa',subject:'Historia',text:history,created:t,sample:true,favorite:false}
]};}
function validPodcastMeta(x){const count=n=>Number.isSafeInteger(n)&&n>=0,finite=n=>typeof n==='number'&&Number.isFinite(n)&&n>=0;const p=x.podcastProgress,j=x.audioJob;if(p&&(!count(p.done)||!count(p.total)||p.done>p.total))return false;if(x.status&&!['draft','review','ready'].includes(x.status))return false;if(x.podcastStats&&(!finite(x.podcastStats.minutes)||!finite(x.podcastStats.plannedMinutes)))return false;if(x.audioSeconds!==undefined&&x.audioSeconds!==null&&!finite(x.audioSeconds))return false;if(j&&(!count(j.done)||!count(j.total)||j.done>j.total||typeof j.signature!=='string'||!/^[a-f0-9]{64}$/.test(j.signature)||!['gemini','openai'].includes(j.provider)||!j.voices||typeof j.voices.Ana!=='string'||typeof j.voices.Leo!=='string'||typeof j.model!=='string'))return false;return true;}
function validItem(x){return x&&typeof x.id==='string'&&x.id.length<150&&['note','deck','podcast','book'].includes(x.type)&&typeof x.title==='string'&&x.title.length<=200&&typeof x.subject==='string'&&x.subject.length<=100&&typeof x.created==='string'&&!Number.isNaN(Date.parse(x.created))&&validPodcastMeta(x)&&(x.type==='deck'?Array.isArray(x.cards)&&(x.cards.length>0||x.status==='draft'&&typeof x.learningJobId==='string')&&x.cards.length<=100&&x.cards.every(c=>typeof c.q==='string'&&typeof c.a==='string'&&c.q.length<=10000&&c.a.length<=10000):typeof x.text==='string'&&(!x.textKey||['note','podcast','book'].includes(x.type)&&['file:'+x.id,'text:'+x.id].includes(x.textKey)));}
function validData(x){return x&&x.version===1&&Array.isArray(x.items)&&x.items.length<=1000&&x.items.every(validItem)&&new Set(x.items.map(i=>i.id)).size===x.items.length&&Array.isArray(x.sessions)&&x.sessions.every(s=>s&&typeof s.date==='string'&&Number.isFinite(s.total)&&Number.isFinite(s.known))&&(!x.calendar||Array.isArray(x.calendar.events)&&x.calendar.events.length<=20000&&x.calendar.events.every(validEvent)&&Array.isArray(x.calendar.sources)&&x.calendar.sources.every(c=>typeof c.id==='string'&&typeof c.name==='string'&&typeof c.url==='string'))&&(!x.subjects||Array.isArray(x.subjects)&&x.subjects.every(s=>s&&typeof s.id==='string'&&typeof s.name==='string'&&s.name.length<=100))&&x.settings&&['ai','basic','opencode',...ONLINE_ENGINES].includes(x.settings.mode)&&typeof x.settings.name==='string';}
