function refreshSearch(){clearTimeout(searchTimer);const version=++searchVersion,value=query;sourceMatches=new Set();searchQuery=value;if(!value.trim())return;searchTimer=setTimeout(async()=>{const found=new Set();try{for(const item of state.items.filter(i=>i.textKey)){if(version!==searchVersion)return;const text=await readDocumentText(item);if(text.toLocaleLowerCase().includes(value.toLocaleLowerCase()))found.add(item.id);}if(version!==searchVersion)return;sourceMatches=found;const focused=document.activeElement?.id==='global-search',pos=$('#global-search')?.selectionStart;render();if(focused){$('#global-search').focus();$('#global-search').setSelectionRange(pos,pos);}}catch(error){toast(error.message);}},200);}
