function meta(i){if(i.learningJobId&&!i.creationComplete)return `${i.progress?.done||0} de ${i.progress?.total||0} bloques · borrador`;if(i.type==='book')return `${i.chapters?.length||0} capítulos · borrador académico`;if(i.format==='source')return `${i.file?.pages?i.file.pages+(i.file.pages===1?' página · ':' páginas · '):''}documento adjunto`;if(i.format==='summary')return `${(i.words??wordCount(i.text))} palabras · resumen`;if(i.notebook)return `${i.pageCount||1} páginas · cuaderno`;if(i.type==='deck')return `${i.cards.length} tarjetas · ${dueCards(i.cards).length} pendientes`;if(i.type==='podcast')return i.status==='draft'?`${i.podcastProgress?.done||0} de ${i.podcastProgress?.total||0} bloques · borrador guardado`:`${i.audioSeconds?timeLabel(i.audioSeconds/60):'~'+timeLabel((i.words??speechWords(i.text))/145)} · ${i.podcastProgress?.total||1} bloques`;return `${(i.words??wordCount(i.text))} palabras`;}
