function heroArt(){return `<div class="hero-art" aria-hidden="true"><div class="hero-orbit"></div><div class="hero-orbit second"></div><div class="hero-focus"><img src="./favicon.svg" alt=""></div><span class="hero-float hero-float-one">${I('cards')}Una idea que se queda</span><span class="hero-float hero-float-two">${I('headphones')}Dale voz a lo que sabes</span></div>`;}
function home(){const recent=state.items.slice().sort((a,b)=>b.created.localeCompare(a.created)).slice(0,3);return `<div class="welcome"><div><h1>Un buen día para aprender<span style="color:#8da772">.</span></h1><p>Organiza tus ideas. Conviértelas en conocimiento.</p></div><span class="date">${I('calendar')}${new Date().toLocaleDateString('es-ES',{day:'numeric',month:'long'})}</span></div><section class="hero"><div class="hero-copy"><div class="eyebrow">${I('spark')}APRENDE A TU MANERA</div><h2>De una idea<br>a todo lo que puedes.</h2><p>Tus apuntes, tus repasos y tu tiempo. Un espacio para entender, recordar y seguir avanzando.</p><div class="hero-buttons"><button data-attach="outline">${I('upload')}Adjuntar archivos</button><button class="hero-text-button" data-create="deck">Crear con IA ${I('arrow')}</button></div></div>${heroArt()}</section><div class="learning-overview"><button data-nav="decks"><span class="overview-icon">${I('cards')}</span><span><strong>${state.items.filter(i=>i.type==='deck').reduce((n,d)=>n+dueCards(d.cards).length,0)}</strong><small>tarjetas para hoy</small></span>${I('arrow')}</button><button data-nav="subjects"><span class="overview-icon">${I('book')}</span><span><strong>${new Set(state.items.map(i=>i.subject)).size}</strong><small>asignaturas a mano</small></span>${I('arrow')}</button><button data-nav="calendar"><span class="overview-icon">${I('calendar')}</span><span><strong>Tu próxima sesión</strong><small>Organiza un rato para ti</small></span>${I('arrow')}</button></div><div class="section-heading"><h2>¿Qué vas a crear hoy?</h2><span class="subtle">Una idea, muchas formas de aprender</span></div><div class="create-grid"><button class="create-card" data-create="note"><span class="tile-icon peach">${I('file')}</span>${I('arrowUp','corner-arrow')}<h3>Un nuevo cuaderno</h3><p>Escribe, dibuja y organiza<br>tus ideas por páginas.</p></button><button class="create-card" data-create="deck"><span class="tile-icon sage">${I('cards')}</span>${I('arrowUp','corner-arrow')}<h3>Tarjetas de estudio</h3><p>Preguntas que te ayudan<br>a recordar de verdad.</p></button><button class="create-card" data-create="podcast"><span class="tile-icon lavender">${I('headphones')}</span>${I('arrowUp','corner-arrow')}<h3>Un podcast</h3><p>Dale voz a tus apuntes.<br>Aprende mientras vas.</p></button></div><button class="file-entry-banner" data-attach="summary"><span class="tile-icon blue">${I('upload')}</span><span><strong>De tus archivos a tus próximos apuntes</strong><small>Adjunta PDF, Word o texto. Crea apuntes, resúmenes, tarjetas y podcasts.</small></span>${I('arrow')}</button><div class="dashboard-bottom"><section><div class="section-heading"><h2>A mano para seguir</h2><button class="link-btn" data-nav="library">Ver biblioteca ${I('arrow')}</button></div><div class="recent-list">${recent.length?recent.map(i=>`<div class="recent-row" data-open="${esc(i.id)}" role="button" tabindex="0"><span class="tile-icon ${types[i.type].color}">${I(types[i.type].icon)}</span><div class="row-info"><h3>${esc(i.title)}</h3><p>${esc(i.subject)} · ${meta(i)}</p></div><span class="row-tag">${i.sample?'Ejemplo':i.format==='source'?'Documento':i.format==='summary'?'Resumen':types[i.type].singular}</span><span class="row-menu">${I('chevron')}</span></div>`).join(''):`<div class="empty"><p>Tu próximo descubrimiento empieza con un apunte.</p><button class="primary" data-create="note">Crear apunte</button></div>`}</div></section><aside>${weekly()}<div class="tip">${I('bulb')}<span>Un pequeño repaso hoy hace más fácil recordar mañana.</span></div></aside></div>`;}
function weekly(){const today=new Date(),monday=new Date(today);monday.setDate(today.getDate()-((today.getDay()+6)%7));const keys=Array.from({length:7},(_,i)=>{const d=new Date(monday);d.setDate(d.getDate()+i);return dateKey(d);});const active=new Set(state.sessions.map(s=>s.date));const days=keys.filter(k=>active.has(k)).length;const total=state.sessions.filter(s=>keys.includes(s.date)).reduce((a,s)=>a+s.total,0);return `<section class="weekly"><h3>${I('leaf')}A tu ritmo, cada día</h3><p>Los pequeños pasos también<br>te llevan muy lejos.</p><div class="days">${['L','M','X','J','V','S','D'].map((d,i)=>`<div class="day"><span>${d}</span><i class="${active.has(keys[i])?'done':keys[i]===dateKey(today)?'today':''}">${active.has(keys[i])?I('check'):keys[i]===dateKey(today)?'·':''}</i></div>`).join('')}</div><div class="weekly-footer"><strong>${days} de 7 días</strong><span>${total} tarjetas repasadas</span></div></section>`;}
function library(){const isBook=page==='books',isDeck=page==='decks',isPod=page==='podcasts',isFav=page==='favorites';const title=query?'Encuentra tu próxima idea':isDeck?'Recuerda un poco más.':isPod?'Aprender también se escucha.':isFav?'Lo que quieres tener cerca.':'Todo tu conocimiento, aquí.';const subtitle=query?`Resultados para «${query}»`:isDeck?'Practica, descubre lo que sabes y vuelve a lo que te cuesta.':isPod?'Tus apuntes, en conversaciones que puedes llevar contigo.':isFav?'Tus apuntes y creaciones favoritas, siempre a mano.':'Apuntes, tarjetas y podcasts. Cada cosa en su lugar.';let items=state.items.filter(i=>(!isBook||i.type==='book')&&(!librarySubject||i.subject===librarySubject)&&(!isDeck||i.type==='deck')&&(!isPod||i.type==='podcast')&&(!isFav||i.favorite)&&(filter==='all'||filter==='summary'&&i.format==='summary'||filter==='note'&&i.type==='note'&&i.format!=='summary'||!['all','summary','note'].includes(filter)&&i.type===filter)&&(!query||`${i.title} ${i.subject} ${i.text||i.cards?.map(c=>c.q+' '+c.a).join(' ')}`.toLowerCase().includes(query.toLowerCase())||query===searchQuery&&sourceMatches.has(i.id))).sort((a,b)=>b.created.localeCompare(a.created));return `<div class="welcome"><div><h1>${title}</h1><p>${esc(subtitle)}</p></div><button class="primary" data-create="${isBook?'book':isDeck?'deck':isPod?'podcast':'note'}">${I('plus')}${isBook?'Crear libro':isDeck?'Crear tarjetas':isPod?'Crear podcast':'Nuevo apunte'}</button></div><div class="toolbar"><div class="filter-tabs">${!isDeck&&!isPod?['all','note','summary','deck','podcast','book'].map(t=>`<button data-filter="${t}" class="${filter===t?'selected':''}">${t==='all'?'Todo':t==='summary'?'Resúmenes':types[t].name}${t==='all'?` · ${items.length}`:''}</button>`).join(''):`<span class="subtle">${items.length} ${isDeck?'mazos de tarjetas':'podcasts'} en tu biblioteca</span>`}</div><button class="link-btn" data-action="export">${I('download')}Copia de seguridad</button></div>${subjectFilter(librarySubject)}<div class="library-grid">${items.length?items.map(resourceCard).join(''):`<div class="empty"><div class="tile-icon sage">${I(query?'search':isFav?'star':'book')}</div><h3>${query?'No hay coincidencias':isFav?'Guarda lo que te inspira':'Tu biblioteca está por empezar'}</h3><p>${query?'Prueba con otro título, asignatura o concepto.':isFav?'Pulsa la estrella de una creación para encontrarla aquí.':'Añade tus primeros apuntes y dales otra forma con IA.'}</p>${!query&&!isFav?'<button class="primary" data-create="note">Crear mi primer apunte</button>':''}</div>`}</div>`;}
function resourceCard(i){const t=types[i.type];return `<article class="resource-card" data-open="${esc(i.id)}" tabindex="0" role="button" aria-label="Abrir ${esc(i.title)}"><div class="resource-cover ${t.color}">${I(t.icon)}<button class="fav ${i.favorite?'on':''}" data-fav="${esc(i.id)}" aria-label="${i.favorite?'Quitar de':'Añadir a'} favoritos" aria-pressed="${!!i.favorite}">${I('star')}</button></div><div class="resource-body"><div class="resource-top"><span class="subject">${esc(i.subject)}</span>${i.sample?'<span class="sample">Ejemplo</span>':`<span class="sample">${i.format==='summary'?'Resumen':i.format==='outline'?'Apuntes':i.format==='source'?'Documento':i.method==='ai'?'IA':i.method==='basic'?'Modo básico':t.singular}</span>`}</div><h3>${esc(i.title)}</h3><p>${esc(i.type==='deck'?i.cards[0]?.q:i.text.replace(/\n/g,' '))}</p><div class="resource-bottom"><span>${I(i.type==='podcast'?'clock':t.icon)}${meta(i)}</span><span>${shortDate(i.created)} ${I('chevron')}</span></div><div class="resource-actions"><button class="link-btn" data-assign-subject="${esc(i.id)}">${I('folder')}Mover</button><button class="link-btn" data-share-item="${esc(i.id)}">${I('upload')}Compartir</button></div></div></article>`;}
function modelProgress(){return `<div class="progress"><div style="width:${Math.round(modelStatus.progress*100)}%"></div></div><p class="progress-label ${modelStatus.error?'error-text':''}" role="status">${esc(modelStatus.error||modelStatus.text)}</p>`;}
function settings(){return `<div class="welcome"><div><h1>Tu espacio, a tu manera.</h1><p>IA gratuita, datos bajo tu control y cero suscripciones.</p></div></div>${providerSettings()}<section class="panel" style="margin-bottom:20px"><h3>Tu framework Studium, integrado</h3><p>Apuntes, resúmenes, tarjetas, libros y podcasts usan los módulos Python originales de Studium para crear proyectos, registrar fuentes y citas y planificar su profundidad. Los informes distinguen las comprobaciones realizadas de las pendientes. La compilación TeX y las verificaciones que necesitan hilos o procesos requieren el framework fuera del navegador.</p><a class="link-btn" href="https://github.com/danielmigueltejedor/studium" target="_blank" rel="noopener">Ver framework Studium</a></section><div class="settings-grid"><section class="panel"><span class="tile-icon sage">${I('spark')}</span><h3>Una IA que vive en tu navegador</h3><p>Qwen2.5 1.5B crea tarjetas y guiones en tu dispositivo con WebLLM. Sin clave API y sin enviar tus apuntes a un servicio de IA.</p><div class="button-row"><span class="model-badge"><i class="status-dot"></i>${modelStatus.ready?'Modelo listo':'Modelo gratuito · local'}</span></div><ul><li>La primera descarga puede ocupar varios cientos de MB.</li><li>Necesita WebGPU y memoria suficiente en tu dispositivo.</li><li>El modelo queda en la caché si el navegador lo permite.</li></ul><div id="model-status">${modelProgress()}</div><div class="button-row"><button class="primary" data-action="load-model" ${modelStatus.loading||modelStatus.ready?'disabled':''}>${I(modelStatus.loading?'loader':'download',modelStatus.loading?'loading-spin':'')}${modelStatus.ready?'IA preparada':modelStatus.loading?'Descargando modelo…':'Preparar IA gratuita'}</button><a class="link-btn" href="https://huggingface.co/mlc-ai/Qwen2.5-1.5B-Instruct-q4f16_1-MLC" target="_blank" rel="noopener">Ver modelo ${I('arrowUp')}</a></div><div class="settings-row"><div><h3 style="font-size:12px;margin-bottom:4px">Motor de creación predeterminado</h3><p>El modo básico extrae frases sin un modelo de IA.</p></div></div><select id="default-engine" class="field" aria-label="Motor de creación predeterminado">${engineOptions(state.settings.mode)}</select><p class="model-disclaimer">Revisa siempre las creaciones: un modelo pequeño puede cometer errores. Los documentos largos se recorren por bloques completos, con citas de cada fuente y avances guardados.</p></section><div style="display:grid;gap:20px;align-content:start"><section class="panel"><span class="tile-icon peach">${I('folder')}</span><h3>Tu biblioteca te pertenece</h3><p>Tu biblioteca se guarda en este dispositivo. Entra en Mi cuenta para conservarla entre equipos, guardar conexiones y elegir la carpeta de iCloud desde la app de iPad. También puedes exportar una copia en cualquier momento.</p><div class="button-row"><button class="secondary" data-action="export">${I('download')}Exportar biblioteca</button><button class="secondary" data-action="import-backup">${I('upload')}Importar copia</button></div><input id="backup-file" class="file-input" type="file" accept="application/json,.json"><label for="space-name" style="display:block;margin:23px 0 9px;font-size:12px">Nombre de tu espacio</label><input id="space-name" class="field" maxlength="40" value="${esc(state.settings.name)}"><div class="button-row"><button class="secondary" data-action="save-name">Guardar nombre</button></div></section><section class="panel"><span class="tile-icon lavender">${I('volume')}</span><h3>Escucha a tu manera</h3><p>Los guiones se leen con las voces disponibles en tu dispositivo. Puedes ajustar la velocidad y descargar el guion. La calidad de voz y su disponibilidad dependen del navegador; algunas voces pueden usar la red.</p><p style="margin-top:10px">Genera y descarga audio de IA desde cada podcast: WAV con Gemini o MP3 con OpenAI. La lectura rápida del dispositivo sigue disponible.</p></section></div></div>`;}
function showModal(title,sub,body,options={}){const modal=$('#modal');modal.innerHTML=`<div class="modal-head"><div><h2>${esc(title)}</h2>${sub?`<p>${esc(sub)}</p>`:''}</div><button class="close" data-action="close" aria-label="Cerrar">${I('close')}</button></div><div class="modal-body">${body}</div>`;if(!modal.open)modal.showModal();if(options.wide)modal.style.maxWidth='740px';else modal.style.maxWidth='640px';}
async function closeModal(){importVersion++;fileReading=false;if(await closeNotebook()===false)return;cancelAudioGeneration();stopRealAudio();onlineController?.abort();if(busy){generationVersion++;busy=false;if(aiWorker){aiWorker.terminate();aiWorker=null;}for(const p of pending.values())p.reject(Error('Creación cancelada.'));pending.clear();modelStatus={ready:false,loading:false,progress:0,text:'Creación cancelada. La descarga ya guardada puede reutilizarse.',error:''};toast('Creación cancelada. Puedes volver a intentarlo.');}stopAudio();$('#modal').close();study=null;}
async function create(type='deck',sourceId=null){const token=++importVersion;const draft={type:type==='note'?'outline':type,sourceId,sourceIds:sourceId?[sourceId]:[],attachments:[],title:'',subject:'',text:'',engine:state.settings.mode,num:6,depth:'UNDERGRADUATE'};try{if(sourceId){const source=await hydrateDocument(getItem(sourceId));draft.title=source.title;draft.subject=source.subject;draft.text=source.text;if(source.file)draft.attachments=[{id:source.id,name:source.file.name,pages:source.file.pages,chars:source.text.length}];}if(token!==importVersion)return;creatorDraft=draft;drawCreator();}catch(error){toast(error.message);}}
function syncDraft(){if(!creatorDraft||!$('#create-form'))return;for(const key of ['title','subject','text','engine','num','depth','domain']){const el=$(`[name="${key}"]`);if(el&&el.dataset.preview!=='true')creatorDraft[key]=el.value;}creatorDraft.sourceId=$('[name="source"]')?.value||null;}
function drawCreator(){const d=creatorDraft,podcastPlan=d.type==='podcast'&&d.text.trim()?createPodcastPlan(d):null,preview=d.text.length>EDITOR_PREVIEW&&!d.editFullText,notes=state.items.filter(i=>['note','book'].includes(i.type));showModal('De tus archivos a tu forma de aprender','Adjunta documentos, comprueba el contenido y elige qué quieres crear.',`<form id="create-form" novalidate>${uploadMarkup(d.attachments)}<label>¿Qué quieres crear?</label><div class="mode-select output-select">${['outline','summary','deck','podcast','book'].map(t=>`<button type="button" data-create-mode="${t}" class="${d.type===t?'chosen':''}">${I(types[t].icon)}${types[t].name}</button>`).join('')}</div><details class="source-details" ${!d.text?'':'open'}><summary>También puedes usar tu biblioteca o pegar texto</summary><label for="source-note">Documento o apunte guardado</label><select class="field" id="source-note" name="source"><option value="">Pegar texto o adjuntar archivos</option>${notes.map(n=>`<option value="${esc(n.id)}" ${d.sourceId===n.id?'selected':''}>${esc(n.file?.name||n.title)}</option>`).join('')}</select><label for="creation-text">Contenido leído · puedes revisarlo y editarlo</label><textarea id="creation-text" class="field" name="text" data-preview="${preview}" ${preview?'readonly':''} placeholder="Pega tus apuntes o adjunta un documento arriba…" required>${esc(preview?d.text.slice(0,EDITOR_PREVIEW):d.text)}</textarea>${preview?'<p class="form-help">Vista previa para agilizar la lectura. Se usará el contenido completo.</p><button class="link-btn" type="button" id="edit-full-source">Editar texto completo</button>':''}<p class="form-help">${d.text.length.toLocaleString('es-ES')} caracteres. Si el documento es largo, se leerá por partes antes de generar el resultado.</p></details><div class="two-cols"><div><label for="creation-title">Título</label><input id="creation-title" class="field" name="title" maxlength="150" placeholder="Por ejemplo, Tema 1 · Biología celular" value="${esc(d.title)}" required></div><div><label for="creation-subject">Asignatura</label><input id="creation-subject" class="field" name="subject" maxlength="60" placeholder="Por ejemplo, Biología" value="${esc(d.subject)}"></div></div><div class="two-cols"><div><label for="creation-engine">Motor de creación</label><select name="engine" id="creation-engine" class="field">${engineOptions(d.engine)}</select></div><div><label for="creation-num">${d.type==='deck'?'Número de tarjetas':'Formato'}</label>${d.type==='deck'?`<select id="creation-num" class="field" name="num">${[6,10,12].map(n=>`<option value="${n}" ${Number(d.num)===n?'selected':''}>${n} tarjetas</option>`).join('')}</select>`:`<div class="field">${d.type==='outline'?'Apuntes organizados por temas':d.type==='summary'?'Ideas principales y conceptos clave':d.type==='book'?'Capítulos con citas · borrador académico':d.engine==='basic'?'Lectura literal · sin guion IA':'Podcast conversacional · 2 voces'}</div>`}</div></div>${d.type==='podcast'?`<label for="podcast-depth">Profundidad del estudio</label><select class="field" id="podcast-depth" name="depth">${[['INTRODUCTORY','Introducción y conceptos esenciales'],['UNDERGRADUATE','Explicación a fondo y conexiones'],['ADVANCED_UNDERGRADUATE','Profundización y límites de aplicación']].map(([value,label])=>`<option value="${value}" ${(d.depth||'UNDERGRADUATE')===value?'selected':''}>${label}</option>`).join('')}</select><div class="notice" style="margin-top:12px">${podcastPlan?`<strong>Duración según el contenido: ~${timeLabel(podcastPlan.minutes)}</strong><br>${podcastPlan.segments.length} bloques · ${podcastPlan.sourceWords.toLocaleString('es-ES')} palabras de fuente. ${d.engine==='basic'?'Este modo lee el texto original. Elige un motor de IA para crear una conversación con preguntas, ejemplos y conexiones.':'Preguntas, ejemplos y conexiones en una conversación original. Se seleccionan las ideas de cada parte: no se lee el documento.'} La duración es orientativa y puede superar las dos horas si el tema lo necesita. El avance se guarda después de cada bloque.`:'Adjunta el manual para calcular su duración y sus bloques de estudio.'}</div>`:''}${d.type!=='podcast'?`<div class="two-cols"><div><label for="material-depth">Nivel del contenido</label><select class="field" id="material-depth" name="depth">${[['INTRODUCTORY','Introducción'],['UNDERGRADUATE','Universitario'],['ADVANCED_UNDERGRADUATE','Universitario avanzado'],['GRADUATE','Posgrado'],['RESEARCH','Investigación']].map(([value,label])=>`<option value="${value}" ${(d.depth||'UNDERGRADUATE')===value?'selected':''}>${label}</option>`).join('')}</select></div><div><label for="material-domain">Área del material</label><select class="field" id="material-domain" name="domain">${[['GENERAL','General'],['STEM','Ciencias e ingeniería'],['LIFE_SCIENCES','Ciencias de la vida'],['HUMANITIES','Humanidades'],['SOCIAL_SCIENCES','Ciencias sociales'],['COMPUTER_SCIENCE','Informática'],['LAW','Derecho']].map(([value,label])=>`<option value="${value}" ${(d.domain||'GENERAL')===value?'selected':''}>${label}</option>`).join('')}</select></div></div>`:''}<div class="notice" id="creator-notice">${esc(engineNotice(d.engine))}</div><div id="generation-status" aria-live="polite"></div><div class="generate-foot"><span>${I('shield')}Fuentes y creaciones guardadas en este navegador</span><button class="primary" type="submit">${I('spark')}Crear ${d.type==='outline'?'apuntes':d.type==='summary'?'resumen':d.type==='deck'?'tarjetas':d.type==='book'?'libro':'podcast'}</button></div></form>`,{wide:true});
$('#create-form').addEventListener('submit',generate);$('#podcast-depth')?.addEventListener('change',()=>{syncDraft();drawCreator();});$('#edit-full-source')?.addEventListener('click',()=>{syncDraft();d.editFullText=true;drawCreator();});$('#source-note').addEventListener('change',async e=>{syncDraft();const id=e.target.value,token=++importVersion;fileReading=true;$('#create-form').querySelectorAll('button,input,select,textarea').forEach(el=>el.disabled=true);try{if(id){const source=await hydrateDocument(getItem(id));if(token!==importVersion)return;d.text=source.text;d.title=source.title;d.subject=source.subject;d.sourceIds=[source.id];d.attachments=source.file?[{id:source.id,name:source.file.name,pages:source.file.pages,chars:source.text.length}]:[];d.editFullText=false;}else{d.sourceIds=[];d.attachments=[];}fileReading=false;drawCreator();}catch(error){fileReading=false;toast(error.message);drawCreator();}});$('#creation-engine').addEventListener('change',()=>{syncDraft();drawCreator();});const token=importVersion;
bindFileUpload({isActive:()=>token===importVersion&&$('#modal').open&&!busy,onStart:()=>{syncDraft();fileReading=true;$('#create-form')?.querySelectorAll('button,input:not([type="file"]),select,textarea').forEach(el=>el.disabled=true);},onEnd:()=>{if(token!==importVersion)return;fileReading=false;$('#create-form')?.querySelectorAll('button,input,select,textarea').forEach(el=>el.disabled=false);},onFiles:async(files,errors)=>{syncDraft();const items=await saveFileSources(files);if(token!==importVersion)return;d.attachments||=[];d.sourceIds||=[];for(const [index,item] of items.entries()){d.attachments.push({id:item.id,name:item.file.name,pages:item.file.pages,chars:item.chars});d.sourceIds.push(item.id);const block=`DOCUMENTO: ${item.file.name}\n${files[index].text}`;d.text=d.text.trim()?d.text.trim()+'\n\n'+block:block;}if(!d.title)d.title=items.length===1?items[0].title:'Materiales de estudio';if(!d.subject)d.subject='General';d.sourceId=d.sourceIds.length===1?d.sourceIds[0]:null;fileReading=false;drawCreator();if(errors.length)$('#file-status').innerHTML=`<div class="notice error-text" role="alert">${errors.map(esc).join('<br>')}</div>`;toast(`${items.length} ${items.length===1?'archivo adjuntado':'archivos adjuntados'}. Ya puedes crear ${d.type==='summary'?'tu resumen':types[d.type].name.toLowerCase()}.`);}});
document.querySelectorAll('[data-detach]').forEach(button=>button.onclick=async()=>{syncDraft();const token=importVersion;try{const id=button.dataset.detach,source=await hydrateDocument(getItem(id));if(token!==importVersion)return;const block=source?`DOCUMENTO: ${source.file.name}\n${source.text}`:'';if(block&&d.text.includes(block))d.text=d.text.replace(block,'').trim();else if(source&&d.text===source.text)d.text='';else{toast('Has editado el texto de esta fuente. Retira primero ese contenido para conservar tus cambios.');return;}d.attachments=d.attachments.filter(x=>x.id!==id);d.sourceIds=d.sourceIds.filter(x=>x!==id);d.sourceId=d.sourceIds.length===1?d.sourceIds[0]:null;drawCreator();}catch(error){toast(error.message);}});}
function basicGenerate(d){return basicStudy(d);}
async function prepareText(d,version){const limit=d.engine==='ai'?4800:40000;if(d.engine==='basic'||d.text.length<=limit)return {text:d.text,parts:1};let chunks=splitSource(d.text,limit),parts=chunks.length,level=0;while(chunks.length>1){level++;const inputLength=chunks.reduce((n,c)=>n+c.length,0);const condensed=[];for(let i=0;i<chunks.length;i++){if(version!==generationVersion)throw Error('Operación cancelada.');const label=`Leyendo el documento completo · parte ${i+1} de ${chunks.length}${level>1?' · síntesis '+level:''}`;$('#generation-status').innerHTML=`<p class="progress-label">${esc(label)}</p>`;let result;if(d.engine==='ai')result=await askWorker('generate',{mode:'summary',brief:true,text:chunks[i],title:d.title,num:Number(d.num)});else result=await onlineGenerate({...d,type:'summary',brief:true,text:chunks[i]},onlineController.signal);if(typeof result!=='string'||result.trim().length<20)throw Error('No se pudo leer una parte del documento. Inténtalo de nuevo.');condensed.push(`Parte ${i+1}\n${result.trim()}`);}const text=condensed.join('\n\n');if(text.length<=limit)return {text,parts};if(text.length>=inputLength)throw Error('El modelo no está resumiendo el contenido. Prueba otro modelo; tu documento completo sigue guardado.');chunks=splitSource(text,limit);}return {text:chunks[0],parts};}

function ensureWorker(){if(aiWorker)return;aiWorker=new Worker('./ai-worker.js',{type:'module'});aiWorker.onmessage=({data:m})=>{if(m.type==='generation-progress'){const target=$('#generation-status');if(target)target.innerHTML=`<p class="progress-label" role="status">${esc(m.text)}</p>`;return;}if(m.type==='progress'){modelStatus={...modelStatus,loading:true,text:`Preparando IA gratuita · ${Math.round(m.progress*100)} %. La primera descarga puede tardar unos minutos.`,progress:m.progress,error:''};refreshProgress();return;}if(m.type==='ready'){modelStatus={ready:true,loading:false,progress:1,text:'Qwen2.5 preparado. Todo listo para crear.',error:''};refreshProgress();}if(m.id&&pending.has(m.id)){const p=pending.get(m.id);pending.delete(m.id);m.error?p.reject(Error(m.error)):p.resolve(m.result);}};aiWorker.onerror=()=>{for(const p of pending.values())p.reject(Error('No se pudo iniciar la IA. Comprueba tu conexión y el soporte WebGPU, o elige el modo básico.'));pending.clear();aiWorker.terminate();aiWorker=null;modelStatus.loading=false;};}
async function askWorker(type,payload={}){if(!navigator.gpu)throw Error('Este navegador no ofrece WebGPU. Abre Studium en un navegador compatible o selecciona «Básico · sin IA ni descarga».');ensureWorker();const id=++requestId;return new Promise((resolve,reject)=>{pending.set(id,{resolve,reject});aiWorker.postMessage({id,type,...payload});});}
function refreshProgress(){const el=$('#model-status');if(el)el.innerHTML=modelProgress();const gen=$('#generation-status');if(gen&&busy)gen.innerHTML=modelProgress();}
async function loadModel(){if(modelStatus.loading||modelStatus.ready)return;modelStatus.loading=true;modelStatus.error='';if(page==='settings')render();try{await askWorker('init');if(page==='settings')render();toast('IA gratuita lista para crear.');}catch(e){modelStatus.loading=false;modelStatus.error=e.message;refreshProgress();if(page==='settings')render();toast(e.message);}}
async function generate(e){e.preventDefault();if(busy)return;if(fileReading){toast('Espera a que termine la lectura de los archivos.');return;}syncDraft();const d={...creatorDraft};d.title=d.title.trim();d.text=d.text.trim();d.subject=d.subject.trim()||'General';if(!d.title||d.text.length<30){toast('Añade un título y al menos 30 caracteres de apuntes.');return;}if(d.type==='note'){const item={id:uid(),type:'note',title:d.title,subject:d.subject,text:d.text,created:now(),sample:false,favorite:false};try{await saveDocument(item,saved=>update(s=>s.items.unshift(saved)));$('#modal').close();page='library';filter='all';query='';render();toast('Apunte guardado. Tu próxima idea ya tiene un lugar.');}catch(error){toast(error.message);}return;}
busy=true;const version=++generationVersion;onlineController=new AbortController();const form=$('#create-form');form.querySelectorAll('input,select,textarea,button').forEach(el=>el.disabled=true);const button=$('button[type="submit"]',form);button.innerHTML=I('loader','loading-spin')+' Creando…';$('#generation-status').innerHTML='<p class="progress-label">Preparando tu creación…</p>';
try{if(d.type==='podcast'){const item=await runPodcastCreation(d,{signal:onlineController.signal,onProgress:message=>{if(version===generationVersion&&$('#generation-status'))$('#generation-status').innerHTML=`<p class="progress-label">${esc(message)}</p><p class="form-help">Puedes cerrar para pausar. Los bloques completados quedan en tu biblioteca.</p>`;},onJob:id=>{creatorDraft.podcastJobId=id;},generate:async(section,signal)=>d.engine==='ai'?askWorker('generate',{mode:'podcast',text:section.text,title:section.title,podcastSection:section.podcastSection}):onlineGenerate({...section,type:'podcast'},signal)});if(version!==generationVersion)return;busy=false;reviewCreation(item);return;}if(['outline','summary','deck','book'].includes(d.type)){const item=await runLearningCreation(d,{signal:onlineController.signal,onJob:id=>{creatorDraft.learningJobId=id;},onProgress:message=>{if(version===generationVersion&&$('#generation-status'))$('#generation-status').textContent=message;},generate:async(block,signal)=>d.engine==='ai'?askWorker('generate',{mode:d.type,text:block.text,title:block.title,num:block.num,educationalBlock:block.educationalBlock}):onlineGenerate(block,signal)});if(version!==generationVersion)return;busy=false;if(item.type==='book')await reviewBook(item);else reviewCreation(item);return;}const prepared=await prepareText(d,version);if(version!==generationVersion)return;let result;if(d.engine==='basic')result=basicGenerate(d);else{modelStatus.error='';if(d.engine==='ai')result=await askWorker('generate',{mode:d.type,text:prepared.text,title:d.title,num:Number(d.num)});else{$('#generation-status').innerHTML='<p class="progress-label">Creando con tu proveedor online…</p>';result=await onlineGenerate({...d,text:prepared.text},onlineController.signal);}if(version!==generationVersion)return;if(d.type==='deck'){let clean=String(result).replace(/```(?:json)?|```/g,'').trim();let start=clean.indexOf('{'),end=clean.lastIndexOf('}');if(start<0||end<0)throw Error('La IA no devolvió tarjetas válidas. Vuelve a intentarlo o utiliza el modo básico.');let json;try{json=JSON.parse(clean.slice(start,end+1));}catch{throw Error('La IA devolvió un formato incorrecto. Vuelve a intentarlo o elige otro modelo.');}result=json.cards;if(!Array.isArray(result))throw Error('El formato generado no es válido. Vuelve a intentarlo.');result=result.filter(c=>c&&typeof c.q==='string'&&typeof c.a==='string'&&c.q.trim()&&c.a.trim()).slice(0,Number(d.num));if(d.engine==='ai'){const normalize=t=>t.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');const source=normalize(d.text);const stop=new Set(['para','como','desde','entre','sobre','porque','tiene','tienen','donde','este','esta','estos','estas','una','unos','unas','son','los','las','del','por','con','que']);const before=result.length;result=result.filter(c=>{const words=normalize(c.a).match(/[a-z0-9]+/g)?.filter(w=>w.length>2&&!stop.has(w))||[];return !words.length||words.filter(w=>source.includes(w)).length/words.length>=.75;});if(result.length<before)toast('Se han descartado respuestas sin apoyo claro en los apuntes. Revisa las tarjetas restantes.');}if(!result.length)throw Error('No se generaron tarjetas utilizables. Prueba con apuntes más claros.');}else if(typeof result!=='string'||result.trim().length<60)throw Error('No se pudo generar el contenido completo. Vuelve a intentarlo.');}
const item={id:uid(),type:['outline','summary'].includes(d.type)?'note':d.type,format:['outline','summary'].includes(d.type)?d.type:undefined,title:d.title,subject:d.subject,created:now(),sourceId:d.sourceId,sourceIds:d.sourceIds||[],readParts:prepared.parts,method:d.engine==='basic'?'basic':'ai',provider:d.engine,sample:false,favorite:false,...(d.type==='deck'?{cards:result}:{text:result.trim()})};busy=false;reviewCreation(item);
}catch(error){if(version!==generationVersion)return;busy=false;modelStatus.loading=false;modelStatus.error=error.message;form.querySelectorAll('input,select,textarea,button').forEach(el=>el.disabled=false);button.innerHTML=I('spark')+' Volver a intentar';$('#generation-status').innerHTML=`<div class="notice error-text" role="alert">${esc(error.message)}</div>`;}}
function reviewCreation(item,truncated=false,editFull=false){const originalText=item.text,preview=['note','podcast','book'].includes(item.type)&&item.text.length>EDITOR_PREVIEW&&!editFull,isNote=item.type==='note',label=isNote?(item.format==='summary'?'resumen':'apuntes'):item.type==='deck'?'tarjetas':'podcast';let body=`<p class="review-warning">${item.method==='ai'?'Creado con IA. Comprueba y edita el contenido antes de guardarlo.':'Creado en modo básico, sin IA. Puedes editarlo antes de guardarlo.'}${item.type==='podcast'&&item.podcastProgress?` Se han desarrollado ${item.podcastProgress.done} bloques del manual. Duración del guion: ~${timeLabel(speechWords(item.text)/145)}. Revisión científica pendiente.`:item.readParts>1?` Se han leído ${item.readParts} partes del documento y sintetizado antes de generar.`:''}${truncated?' Se usó el fragmento inicial del apunte por el límite del motor elegido.':''}</p><form id="review-form">`;if(item.type==='deck')body+=`<div class="edit-cards">${item.cards.map((c,i)=>`<div class="edit-card"><label for="q-${i}">TARJETA ${i+1} · PREGUNTA</label><textarea id="q-${i}" class="field" name="q-${i}" required maxlength="10000">${esc(c.q)}</textarea><label for="a-${i}">RESPUESTA</label><textarea id="a-${i}" class="field" name="a-${i}" required maxlength="10000">${esc(c.a)}</textarea></div>`).join('')}</div>`;else body+=`<label for="review-script">${isNote?(item.format==='summary'?'Resumen del documento':'Apuntes organizados'):'Guion del podcast'}</label><textarea class="field" id="review-script" data-preview="${preview}" ${preview?'readonly':''} style="min-height:300px" required>${esc(preview?item.text.slice(0,EDITOR_PREVIEW):item.text)}</textarea>${preview?'<p class="form-help">Vista previa. Se guardará todo el texto generado.</p><button class="link-btn" type="button" id="edit-full-review">Editar texto completo</button>':''}${isNote?'':'<p class="form-help">Solo intervienen Ana: y Leo:. Cada personaje conservará una voz fija. Las evidencias se pueden consultar desde el podcast guardado.</p>'}`;body+=`<div class="button-row"><button type="submit" class="primary">${I('check')}Guardar ${label}</button><button type="button" class="secondary" data-action="back-creator">Volver a los documentos</button></div></form>`;showModal('Un último vistazo',`${item.title} · ${item.type==='deck'?item.cards.length+' tarjetas':isNote?(item.format==='summary'?'Resumen listo':'Apuntes listos'):'Guion listo para escuchar'}`,body);$('#edit-full-review')?.addEventListener('click',()=>reviewCreation(item,truncated,true));$('#review-form').addEventListener('submit',async e=>{e.preventDefault();if(item.type==='deck')item.cards=item.cards.map((c,i)=>({...c,q:$(`#q-${i}`).value.trim(),a:$(`#a-${i}`).value.trim()}));else if($('#review-script').dataset.preview!=='true')item.text=$('#review-script').value.trim();if(item.type==='deck'?item.cards.some(c=>!c.q||!c.a):!item.text){toast('Completa el contenido antes de guardar.');return;}try{if(item.type==='podcast'){parseDialogue(item.text);item.status='ready';if(item.text!==originalText){item.audioRevision=null;item.audioJob=null;item.quality={...item.quality,sourceQuotes:'STALE_AFTER_EDIT',scientificReview:'PENDING'};}}await saveDocument(item,saved=>update(s=>{const index=s.items.findIndex(i=>i.id===saved.id);if(index<0)s.items.unshift(saved);else s.items[index]={...s.items[index],...saved};}));$('#modal').close();page=item.type==='deck'?'decks':item.type==='podcast'?'podcasts':'library';query='';filter='all';render();toast('Creación guardada en tu biblioteca.');openItem(item.id);}catch(error){toast(error.message);}});}

function openItem(id){const item=getItem(id);if(!item)return;if(item.learningJobId&&!item.creationComplete){showLearningDraft(item);return;}if(item.type==='book'){openBook(item);return;}if(item.type==='note'&&(item.notebook||isPdfItem(item)))hydrateDocument(item).then(openNotebook).catch(error=>toast(error.message));else if(item.type==='note')openNote(item);else if(item.type==='deck')startStudy(item);else openPodcast(item);}
async function openNote(item,showFull=false){try{item=await hydrateDocument(item);const preview=item.text.length>EDITOR_PREVIEW&&!showFull;showModal(item.title,`${item.subject} · ${meta(item)}${item.sample?' · Apunte de ejemplo':''}`,`<span class="model-badge">${I('file')}${item.format==='source'?'Documento adjunto':item.format==='summary'?'Resumen guardado':'Apuntes guardados'}</span>${item.file?`<p class="form-help" style="margin-top:12px">${esc(item.file.name)} · archivo original conservado</p>`:''}<div class="note-content">${richTextHTML(preview?item.text.slice(0,EDITOR_PREVIEW):item.text)}</div>${preview?`<p class="form-help">Vista previa · ${item.text.length.toLocaleString('es-ES')} caracteres guardados. Las creaciones y descargas usan el texto completo.</p><button class="secondary" data-show-full-note="${esc(item.id)}">Mostrar texto completo</button>`:''}<div class="note-actions"><button class="secondary" data-framework-report="${esc(item.id)}">${I('shield')}Proyecto Studium</button><button class="secondary" data-from-note="${esc(item.id)}" data-type="book">${I('book')}Crear libro académico</button>${item.sourceIds?.length?`<button class="secondary" data-view-sources="${esc(item.id)}">${I('folder')}Ver fuentes</button>`:''}${item.file?`<button class="secondary" data-source-file="${esc(item.id)}">${I('download')}Archivo original</button>`:''}<button class="secondary" data-from-note="${esc(item.id)}" data-type="outline">${I('file')}Crear apuntes</button><button class="secondary" data-from-note="${esc(item.id)}" data-type="summary">${I('book')}Crear resumen</button><button class="secondary" data-notebook="${esc(item.id)}">${I('book')}Abrir como cuaderno</button><button class="primary" data-from-note="${esc(item.id)}" data-type="deck">${I('cards')}Crear tarjetas</button><button class="secondary" data-from-note="${esc(item.id)}" data-type="podcast">${I('headphones')}Crear podcast</button><button class="secondary" data-edit="${esc(item.id)}" aria-label="Editar apunte">${I('edit')}</button><button class="secondary" data-download="${esc(item.id)}" aria-label="Descargar apunte">${I('download')}</button><button class="danger" data-delete="${esc(item.id)}" aria-label="Eliminar apunte">${I('trash')}</button></div>`);decorateMath(document.querySelector('#modal')).catch(error=>toast(error.message));}catch(error){toast(error.message);}}
async function editNote(item){try{item=await hydrateDocument(item);}catch(error){toast(error.message);return;}showModal('Cada idea puede crecer',item.title,`<form id="edit-note-form"><label for="edit-title">Título</label><input id="edit-title" class="field" maxlength="150" value="${esc(item.title)}" required><label for="edit-subject">Asignatura</label><input id="edit-subject" class="field" maxlength="60" value="${esc(item.subject)}"><label for="edit-text">Tus apuntes</label><textarea id="edit-text" class="field" style="min-height:270px" required>${esc(item.text)}</textarea><div class="button-row"><button class="primary">${I('check')}Guardar cambios</button></div></form>`);$('#edit-note-form').addEventListener('submit',async e=>{e.preventDefault();const title=$('#edit-title').value.trim(),text=$('#edit-text').value.trim(),subject=$('#edit-subject').value.trim()||'General';if(!title||text.length<30){toast('Añade un título y al menos 30 caracteres.');return;}try{await saveDocument({...item,title,subject,text,framework:item.framework?{...item.framework,status:'STALE_AFTER_EDIT',released:false}:undefined,updated:now(),sample:false},saved=>update(s=>Object.assign(s.items.find(x=>x.id===item.id),saved)));render();openNote(getItem(item.id));toast('Cambios guardados.');}catch(error){toast(error.message);}});}
function startStudy(item,practice=false){if(!update(data=>{const d=data.items.find(i=>i.id===item.id);for(const c of d.cards)c.id||=uid();}))return;study={id:item.id,flipped:false,results:[],finished:false,practice,seen:[]};drawStudy();}
function drawStudy(){if(!study)return;const d=getItem(study.id);if(!d)return;const pending=study.practice?d.cards.filter(c=>!study.seen.includes(c.id)):dueCards(d.cards),c=pending[0];study.cardId=c?.id;if(!c){study.finished=true;const next=nextReview(d.cards),known=study.results.filter(r=>r>=2).length;showModal(d.title,'Tu próximo repaso, en su momento.',`<div class="study-result"><span class="tile-icon sage">${I('leaf')}</span><h3>${study.results.length?'Repaso guardado.':'Todo al día.'}</h3><p>${study.results.length?`Has respondido ${study.results.length} tarjetas; ${known} recordadas.<br>`:''}${next?`Próximo repaso: ${esc(next.toLocaleString('es-ES',{dateStyle:'medium',timeStyle:'short'}))}.`:'Este mazo está listo para empezar.'}</p><p class="form-help">Otra vez = no la recuerdas. Difícil, Bien y Fácil = la recuerdas con distinto esfuerzo. FSRS calcula cuándo volverá a aparecer.</p><div class="study-buttons"><button class="primary" data-open="${esc(d.id)}">Comprobar pendientes</button><button class="secondary" data-practice-deck="${esc(d.id)}">Practicar sin cambiar fechas</button><button class="secondary" data-action="close">Terminar</button></div></div>`);return;}study.finished=false;const options=study.flipped?reviewOptions(c):[];showModal(d.title,`${d.subject} · ${study.practice?'Práctica libre · conserva tus fechas':'Repaso espaciado · FSRS'}`,`<div class="study-meta"><span>${pending.length} ${study.practice?'por practicar':'pendientes ahora'}</span><span>${study.results.length} respuestas guardadas</span></div><button class="flashcard ${study.flipped?'answer':''}" data-action="flip"><span class="eyebrow">${study.flipped?'LA RESPUESTA':'PON A PRUEBA TU MEMORIA'}</span><p>${esc(study.flipped?c.a:c.q)}</p><small>${study.flipped?'¿Cuánto esfuerzo te ha costado recordarla?':'Pulsa para ver la respuesta'} ${I('refresh')}</small></button><div class="study-buttons study-ratings">${study.flipped?options.map(o=>`<button class="rating rating-${o.rating}" data-study-score="${o.rating}"><strong>${['','Otra vez','Difícil','Bien','Fácil'][o.rating]}</strong><small>${study.practice?'Sin cambiar fecha':intervalLabel(o.due)}</small></button>`).join(''):`<button class="primary" data-action="flip">Ver respuesta ${I('arrow')}</button>`}</div><p class="form-help">${study.practice?'La práctica libre no modifica el calendario de repasos.':'Las fechas y tu progreso se guardan al responder, también si cierras la sesión.'}</p><div class="note-actions" style="justify-content:flex-end"><button class="link-btn" data-framework-report="${esc(d.id)}">${I('shield')}Proyecto Studium</button><button class="link-btn" data-share-item="${esc(d.id)}">${I('upload')}Compartir</button><button class="link-btn" data-edit-deck="${esc(d.id)}">${I('edit')}Editar</button><button class="link-btn" data-download="${esc(d.id)}">${I('download')}Exportar</button><button class="link-btn" data-delete="${esc(d.id)}">${I('trash')}Eliminar</button></div>`);}
function scoreStudy(rating){if(!study||!study.flipped||study.finished)return;const d=getItem(study.id),index=d.cards.findIndex(c=>c.id===study.cardId);if(index<0)return;try{if(!study.practice&&!update(s=>{const deck=s.items.find(i=>i.id===d.id);deck.cards[index]=scheduleAnswer(deck.cards[index],rating);s.sessions.push({id:uid(),date:dateKey(new Date()),total:1,known:rating>=2?1:0,deckId:d.id});}))return;study.results.push(rating);study.seen.push(study.cardId);study.flipped=false;drawStudy();}catch(error){toast(error.message);}}
function editDeck(item){study=null;reviewCreation(structuredClone(item));const form=$('#review-form');const clone=form.cloneNode(true);form.replaceWith(clone);clone.addEventListener('submit',e=>{e.preventDefault();let cards=item.cards.map((c,i)=>({...c,q:$(`#q-${i}`).value.trim(),a:$(`#a-${i}`).value.trim()}));cards=cards.map((c,i)=>c.q===item.cards[i].q&&c.a===item.cards[i].a?c:{id:uid(),q:c.q,a:c.a});if(cards.some(c=>!c.q||!c.a)){toast('Completa las preguntas y respuestas.');return;}if(update(s=>Object.assign(s.items.find(x=>x.id===item.id),{cards,framework:item.framework?{...item.framework,status:'STALE_AFTER_EDIT',released:false}:undefined,updated:now(),sample:false}))){render();toast('Tarjetas actualizadas.');startStudy(getItem(item.id));}});}
async function openPodcast(item){try{item=await hydrateDocument(item);}catch(error){toast(error.message);return;}stopAudio();stopRealAudio();player={...player,id:item.id,chunks:[],voiceMap:null,index:0,playing:false,paused:false};try{player.chunks=parseDialogue(item.text);}catch{player.chunks=[];}let bars=Array.from({length:55},(_,i)=>`<i style="height:${12+Math.abs(Math.sin(i*.72)*60)+Math.abs(Math.cos(i*.3)*25)}px"></i>`).join('');showModal('Dale al play. Sigue aprendiendo.',item.sample?'Podcast de ejemplo · voces del dispositivo':'Podcast guardado · voces del dispositivo',`<div class="podcast-art"><div class="wave">${bars}</div>${I('headphones')}</div><div class="podcast-info"><h3>${esc(item.title)}</h3><p>${esc(item.subject)} · ${meta(item)}</p></div>${item.status==='draft'||item.status==='review'?`<div class="notice">${item.status==='draft'?'La creación está pausada. Los bloques completados están guardados.'+(item.podcastProgress?.pendingWords?' También se conservan '+item.podcastProgress.pendingWords+' palabras del bloque en ampliación.':''):'El guion completo está pendiente de tu revisión.'}<div class="button-row"><button class="primary" data-resume-podcast="${esc(item.id)}">${item.status==='draft'?'Continuar creación':'Revisar y guardar guion'}</button></div></div>`:''}${item.podcastJobId?`<div class="button-row"><button class="secondary" data-podcast-evidence="${esc(item.podcastJobId)}">Ver contenidos y fuentes</button></div>`:''}<div id="saved-audio"></div><div class="button-row" style="justify-content:center"><button class="primary" data-ai-audio="${esc(item.id)}" ${item.status==='draft'?'disabled':''}>${I('spark')}${item.audioRevision?'Volver a generar audio IA':'Generar audio con IA'}</button></div><p class="form-help" style="text-align:center;margin-top:18px">Lectura rápida con la voz del dispositivo</p><div class="player-controls"><button class="secondary" data-action="restart-audio" aria-label="Volver al inicio">${I('refresh')}</button><button class="play-big" id="audio-play" data-action="toggle-audio" aria-label="Reproducir podcast">${I('play')}</button><select id="audio-rate" class="speed" aria-label="Velocidad de reproducción">${[.75,1,1.25,1.5].map(n=>`<option value="${n}" ${player.rate===n?'selected':''}>${n}×</option>`).join('')}</select></div><div class="progress"><div id="audio-progress" style="width:0%"></div></div><div class="player-timeline"><span id="audio-status" aria-live="polite">Listo para escuchar</span><span>~${timeLabel(speechWords(item.text)/145)}</span></div><details class="transcript"><summary>Leer el guion</summary><p>${esc(item.text)}</p></details><p class="form-help" style="margin-top:15px">Se usan las voces en español de tu dispositivo. La duración es aproximada. Puedes guardar el guion para leerlo sin sonido.</p><div class="note-actions"><button class="secondary" data-framework-report="${esc(item.id)}">${I('shield')}Proyecto Studium</button>${item.podcastJobId||item.sourceIds?.length||item.sourceId?`<button class="secondary" data-rebuild-podcast="${esc(item.id)}">Crear versión conversacional desde las fuentes</button>`:''}<button class="secondary" data-download="${esc(item.id)}">${I('download')}Descargar guion</button><button class="secondary" data-edit-podcast="${esc(item.id)}">${I('edit')}Editar</button><button class="danger" data-delete="${esc(item.id)}" aria-label="Eliminar podcast">${I('trash')}</button></div>`);$('#audio-rate').addEventListener('change',e=>{player.rate=Number(e.target.value);if(player.playing||player.paused){speechSynthesis.cancel();player.token++;player.paused=false;player.playing=true;speakChunk();}});attachAudioPlayer(item);}
function updatePlayer(){const el=$('#audio-play');if(!el)return;el.innerHTML=I(player.playing?'pause':'play');el.setAttribute('aria-label',player.playing?'Pausar podcast':'Reproducir podcast');$('#audio-progress').style.width=`${player.chunks.length?Math.round(player.index/player.chunks.length*100):0}%`;$('#audio-status').textContent=player.playing?`Escuchando · fragmento ${player.index+1} de ${player.chunks.length}`:player.paused?'En pausa':player.index>=player.chunks.length?'Has llegado al final. ¡Buen repaso!':'Listo para escuchar';}
let utterance=null;
function fixDeviceVoices(){if(player.voiceMap)return;const voices=speechSynthesis.getVoices().filter(v=>v.lang.toLowerCase().startsWith('es'));if(!voices.length)throw Error('Espera a que el navegador cargue las voces en español y vuelve a reproducir.');player.voiceMap={Ana:voices[0],Leo:voices[1]||voices[0]};}
function speakChunk(){if(player.index>=player.chunks.length){player.playing=false;player.paused=false;updatePlayer();return;}const token=++player.token,turn=player.chunks[player.index];try{fixDeviceVoices();}catch(error){player.playing=false;toast(error.message);updatePlayer();return;}utterance=new SpeechSynthesisUtterance(turn.text);utterance.lang='es-ES';utterance.rate=player.rate;utterance.voice=player.voiceMap[turn.speaker];utterance.onend=()=>{if(token!==player.token)return;player.index++;if(player.playing)speakChunk();};utterance.onerror=e=>{if(token!==player.token||['interrupted','canceled'].includes(e.error))return;player.playing=false;player.paused=false;updatePlayer();toast('La voz no está disponible. Revisa las voces del dispositivo o lee el guion.');};speechSynthesis.speak(utterance);updatePlayer();}
function toggleAudio(){pauseRealAudio();if(!('speechSynthesis'in window)){toast('Este navegador no admite lectura en voz alta. Puedes descargar el guion.');return;}if(player.playing){speechSynthesis.pause();player.playing=false;player.paused=true;updatePlayer();return;}if(player.paused){speechSynthesis.resume();player.playing=true;player.paused=false;updatePlayer();return;}if(player.index>=player.chunks.length)player.index=0;player.playing=true;speakChunk();}
function stopAudio(){player.token++;if('speechSynthesis'in window)speechSynthesis.cancel();player.playing=false;player.paused=false;}
async function editPodcast(item){try{item=await hydrateDocument(item);}catch(error){toast(error.message);return;}stopAudio();reviewCreation(structuredClone(item));const form=$('#review-form'),clone=form.cloneNode(true);form.replaceWith(clone);clone.addEventListener('submit',async e=>{e.preventDefault();const text=$('#review-script').dataset.preview==='true'?item.text:$('#review-script').value.trim();if(!text){toast('El guion no puede estar vacío.');return;}try{parseDialogue(text);await saveDocument({...item,text,quality:{...item.quality,scientificReview:'PENDING',sourceQuotes:'STALE_AFTER_EDIT'},audioRevision:null,audioJob:null,updated:now(),sample:false},saved=>update(s=>Object.assign(s.items.find(x=>x.id===item.id),saved)));render();openPodcast(getItem(item.id));toast('Guion actualizado. Las evidencias deben revisarse tras editar.');}catch(error){toast(error.message);}});}
function confirmDelete(item){stopAudio();showModal('¿Eliminar de tu biblioteca?',item.title,`<p style="font-size:13px;color:#829176;line-height:1.8">Se eliminará ${item.type==='note'?'este apunte':item.type==='deck'?'este mazo de tarjetas':'este podcast'} de este navegador. Las otras creaciones se conservarán. Puedes exportar una copia antes de continuar.</p><div class="button-row"><button class="danger" id="confirm-delete">${I('trash')}Eliminar</button><button class="secondary" data-open="${esc(item.id)}">Conservar</button></div>`);$('#confirm-delete').onclick=()=>{if(update(s=>s.items=s.items.filter(i=>i.id!==item.id))){deleteItemAssets(item.id).catch(()=>{});study=null;$('#modal').close();render();toast('Eliminado de la biblioteca.');}};}
function download(name,text,type='text/plain'){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
async function exportLibrary(){try{toast('Preparando la biblioteca y sus archivos…');const data=structuredClone(state);data.assets=[];const ids=new Set(data.items.map(i=>i.id));for(const asset of await allAssets()){const itemId=assetOwnerId(asset);if(!ids.has(itemId))continue;data.assets.push({id:asset.id,kind:asset.kind,data:['audio','file','audio-segment','notebook-media','notebook-pdf'].includes(asset.kind)?{...asset.data,blob:await blobBase64(asset.data.blob)}:asset.data});}download(`studium-biblioteca-${dateKey(new Date())}.json`,JSON.stringify(data),'application/json');toast('Copia completa descargada: incluye documentos, cuadernos y audio de IA.');}catch(e){toast('No se pudo exportar: '+e.message);}}

async function downloadItem(item){try{if(['note','podcast','book'].includes(item.type))item=await hydrateDocument(item);const filename=item.title.replace(/[^\p{L}\p{N} _-]/gu,'').slice(0,80);if(item.type==='deck')download(`${filename}.json`,JSON.stringify({title:item.title,subject:item.subject,cards:item.cards},null,2),'application/json');else download(`${filename}.txt`,`${item.title}\n${item.subject}\n\n${item.text}`);}catch(error){toast(error.message);}}

async function importBackup(e){const file=e.target.files[0];if(!file)return;try{const data=JSON.parse(await file.text());if(!validData(data))throw Error('Esta copia no tiene un formato válido de Studium.');const assets=data.assets||[];if(!Array.isArray(assets)||assets.length>4000)throw Error('Los archivos de la copia no son válidos.');for(const a of assets){if(!a||typeof a.id!=='string'||!['notebook','audio','file','text','podcast-job','audio-segment','notebook-media','notebook-pdf','framework-project','learning-job'].includes(a.kind)||!a.id.startsWith(a.kind+':')||!data.items.some(i=>assetOwnerId(a)===i.id)||a.kind==='audio-segment'&&(!a.id.startsWith('audio-segment:'+a.data.itemId+':')||!/^\d+$/.test(a.id.slice(('audio-segment:'+a.data.itemId+':').length))))throw Error('La copia contiene un archivo no válido.');if(a.kind==='framework-project'&&!validFrameworkProject(a.data,assetOwnerId(a))||a.kind==='learning-job'&&!validLearningJob(a.data,assetOwnerId(a)))throw Error('Un proyecto o borrador de Studium no es válido.');if(a.kind==='text'&&typeof a.data?.text!=='string')throw Error('El texto de la copia no es válido.');if(a.kind==='file'&&a.data?.text!==undefined&&typeof a.data.text!=='string')throw Error('El texto adjunto no es válido.');if(a.kind==='notebook'&&!validateNotebook(a.data))throw Error('Un cuaderno de la copia no es válido.');if(a.kind==='audio-segment'&&(typeof a.data?.blob!=='string'||typeof a.data.signature!=='string'||!['Ana','Leo'].includes(a.data.speaker)||typeof a.data.voice!=='string'||typeof a.data.model!=='string'))throw Error('Un fragmento de audio no es válido.');if(a.kind==='podcast-job'&&(!validPodcastJob(a.data,a.id.slice(12))))throw Error('Un borrador de podcast no es válido.');if(a.kind==='audio'&&(typeof a.data?.blob!=='string'||typeof a.data.revision!=='string'||typeof a.data.provider!=='string'))throw Error('El audio de la copia no es válido.');}for(const a of assets){if(['notebook-media','notebook-pdf'].includes(a.kind)&&(typeof a.data?.blob!=='string'||!/^data:(image\/(png|jpeg|webp)|application\/pdf);base64,[A-Za-z0-9+/=]+$/.test(a.data.blob)||!a.id.startsWith(a.kind+':'+a.data.itemId+':')))throw Error('Una figura o PDF del cuaderno no es válido.');if(a.kind==='file'&&(typeof a.data?.blob!=='string'||a.data.blob.length>36000000||typeof a.data.name!=='string'||a.data.name.length>300||!/^data:(application\/(pdf|octet-stream|vnd.openxmlformats-officedocument.wordprocessingml.document)|text\/(plain|markdown));base64,[A-Za-z0-9+/=]+$/.test(a.data.blob)))throw Error('El documento adjunto de la copia no es válido.');}for(const item of data.items){if(item.textKey&&!assets.some(a=>a.id===item.textKey&&typeof a.data?.text==='string'))throw Error('La copia no contiene el texto completo de '+item.title+'. Exporta de nuevo la biblioteca de origen.');}const existing=new Set(state.items.map(i=>i.id));const restored=[];for(const a of assets){if(existing.has(assetOwnerId(a)))continue;await putAsset(a.id,a.kind,['audio','file','audio-segment','notebook-media','notebook-pdf'].includes(a.kind)?{...a.data,blob:['audio','audio-segment'].includes(a.kind)?base64Blob(a.data.blob):new Blob([Uint8Array.from(atob(a.data.blob.split(',')[1]),c=>c.charCodeAt(0))],{type:a.data.blob.slice(5,a.data.blob.indexOf(';'))})}:a.data);restored.push(a.id);}for(let index=0;index<data.items.length;index++){const item=data.items[index];if(!existing.has(item.id)&&['note','podcast','book'].includes(item.type)&&!item.textKey&&item.text.length>TEXT_PREVIEW){data.items[index]=await saveDocument(item,()=>true);restored.push('text:'+item.id);}}let added=0;const ok=update(s=>{if(data.calendar){s.calendar||={events:[],sources:[]};const eventIds=new Set(s.calendar.events.map(e=>e.id));s.calendar.events.push(...data.calendar.events.filter(e=>!eventIds.has(e.id)));const sourceIds=new Set(s.calendar.sources.map(c=>c.id));s.calendar.sources.push(...data.calendar.sources.filter(c=>!sourceIds.has(c.id)));}s.subjects||=[];for(const folder of data.subjects||[])if(!s.subjects.some(x=>x.name===folder.name))s.subjects.push(folder);const ids=new Set(s.items.map(i=>i.id));data.items.forEach(i=>{if(!ids.has(i.id)){s.items.push(i);ids.add(i.id);added++;}});const sessionKeys=new Set(s.sessions.map(x=>JSON.stringify(x)));data.sessions.forEach(x=>{if(!sessionKeys.has(JSON.stringify(x))){s.sessions.push(x);sessionKeys.add(JSON.stringify(x));}});});if(ok){render();toast(`${added} elementos importados con sus archivos. Tu biblioteca actual se conserva.`);}else await deleteAssets(restored);}catch(err){toast(err.message);}}

function help(){showModal('Aprender tiene muchas formas.','Empieza con una idea. Hazla tuya.',`<div class="panel" style="border:0;padding:0"><h3>1. Guarda tus apuntes</h3><p>Escribe, pega texto o importa un TXT, Markdown o PDF con texto. Todo se guarda en este navegador. El editor de cuadernos permite texto, bolígrafo, resaltador, borrador, páginas y anotaciones sobre PDF.</p><h3 style="margin-top:22px">2. Dales otra forma</h3><p>Crea tarjetas y podcasts con IA local gratuita o conecta OpenRouter Free, Gemini, Groq y OpenAI desde Ajustes. Los proveedores online necesitan tu clave. El filtro de opciones gratuitas está activo por defecto.</p><h3 style="margin-top:22px">3. Repasa a tu ritmo</h3><p>Gira las tarjetas y registra lo que recuerdas. En cada podcast puedes generar audio real con IA, guardarlo y descargarlo. También tienes una lectura rápida con las voces del dispositivo. Revisa las creaciones antes de estudiar.</p><div class="notice">Tu biblioteca no se sincroniza. Exporta copias desde Ajustes para conservarla o pasarla a otro equipo. Los elementos marcados como «Ejemplo» te ayudan a probar la app.</div><div class="button-row"><button class="primary" data-create="note">${I('plus')}Crear mi primer apunte</button></div></div>`);}
document.addEventListener('click',e=>{const b=e.target.closest('button,[data-open],[data-action],[data-attach]');if(!b)return;
if(b.dataset.attach){stopAudio();stopRealAudio();study=null;create(b.dataset.attach);return;}
if(b.dataset.fav){e.stopPropagation();if(update(s=>{const i=s.items.find(i=>i.id===b.dataset.fav);i.favorite=!i.favorite;}))render();return;}
if(b.dataset.nav){if(b.dataset.action==='close')closeModal();page=b.dataset.nav;if(globalThis.location)location.hash=page==='community'?'comunidad':page==='account'?'cuenta':'';librarySubject='';query='';filter='all';menu=false;render();return;}
if(b.dataset.create){stopAudio();stopRealAudio();study=null;if(b.dataset.create==='note')newNotebook();else create(b.dataset.create);return;}
if(b.dataset.createMode){if(fileReading)return;syncDraft();creatorDraft.type=b.dataset.createMode;drawCreator();return;}
if(b.dataset.filter){filter=b.dataset.filter;render();return;}
if(b.dataset.practiceDeck){startStudy(getItem(b.dataset.practiceDeck),true);return;}
if(b.dataset.open){openItem(b.dataset.open);return;}
if(b.dataset.rebuildPodcast){rebuildPodcastCreation(b.dataset.rebuildPodcast);return;}
if(b.dataset.resumeLearning){resumeLearningCreation(b.dataset.resumeLearning);return;}if(b.dataset.resumePodcast){resumePodcastCreation(b.dataset.resumePodcast);return;}
if(b.dataset.fromNote){create(b.dataset.type,b.dataset.fromNote);return;}
if(b.dataset.showFullNote){openNote(getItem(b.dataset.showFullNote),true);return;}
if(b.dataset.edit){editNote(getItem(b.dataset.edit));return;}
if(b.dataset.editDeck){editDeck(getItem(b.dataset.editDeck));return;}
if(b.dataset.editPodcast){editPodcast(getItem(b.dataset.editPodcast));return;}
if(b.dataset.download){downloadItem(getItem(b.dataset.download));return;}
if(b.dataset.delete){confirmDelete(getItem(b.dataset.delete));return;}
if(b.dataset.studyScore!==undefined){scoreStudy(Number(b.dataset.studyScore));return;}
switch(b.dataset.action){case 'close':closeModal();break;case 'menu':menu=!menu;render();break;case 'help':help();break;case 'export':exportLibrary();break;case 'import-backup':$('#backup-file').click();break;case 'back-creator':drawCreator();break;case 'flip':if(study&&!study.finished){study.flipped=!study.flipped;drawStudy();}break;case 'toggle-audio':toggleAudio();break;case 'restart-audio':{const id=player.id;openPodcast(getItem(id));toggleAudio();break;}case 'load-model':loadModel();break;case 'save-name':{const name=$('#space-name').value.trim()||'Mi espacio';if(update(s=>s.settings.name=name)){render();toast('Tu espacio ya tiene nombre.');}break;}}
});
document.addEventListener('change',e=>{if(e.target.id==='default-engine'){if(update(s=>s.settings.mode=e.target.value))toast('Motor predeterminado actualizado.');}if(e.target.id==='backup-file')importBackup(e);});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();$('#global-search').focus();}if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))return;if((e.key==='Enter'||e.key===' ')&&e.target.matches('.resource-card,.recent-row')){e.preventDefault();openItem(e.target.dataset.open);return;}if(study&&$('#modal').open&&!study.finished&&e.key===' '){e.preventDefault();study.flipped=!study.flipped;drawStudy();}});
$('#modal').addEventListener('cancel',e=>{e.preventDefault();closeModal();});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
window.addEventListener('pagehide',()=>{stopAudio();aiWorker?.terminate();});
window.addEventListener('storage',e=>{if(e.key!==KEY)return;try{const latest=JSON.parse(e.newValue);if(validData(latest)){state=latest;render();}}catch{}});
render();if(storageIssue)setTimeout(()=>toast('No se pudo leer o guardar la biblioteca. Comprueba el almacenamiento del navegador y exporta una copia.'),500);

async function resumeLearningCreation(id){try{const job=(await getAsset('learning-job:'+id))?.data;if(!job)throw Error('No se encuentra el avance guardado.');creatorDraft={...job.input,learningJobId:id};drawCreator();await generate({preventDefault(){}});}catch(error){toast(error.message);}}
export function replaceLibrary(data){if(!validData(data))throw Error('La biblioteca guardada no tiene un formato válido.');localStorage.setItem(KEY,JSON.stringify(data));state=data;render();}
export function setLibrarySubject(name){librarySubject=name;page='library';query='';filter='all';render();}
export {exportLibrary,askWorker,I,esc,state,update,render,toast,showModal,getItem,stopAudio,openPodcast,openItem,create,confirmDelete};
document.addEventListener('click',e=>{const n=e.target.closest('[data-notebook]');if(n)hydrateDocument(getItem(n.dataset.notebook)).then(openNotebook).catch(error=>toast(error.message));});

async function resumePodcastCreation(id){try{const job=await readPodcastJob(id);creatorDraft={...job.input,num:6,podcastJobId:id,attachments:[],editFullText:false};importVersion++;drawCreator();await generate({preventDefault(){}});}catch(error){toast(error.message);}}

async function rebuildPodcastCreation(id){try{const item=getItem(id);let input;if(item.podcastJobId){input=(await readPodcastJob(item.podcastJobId)).input;}else{const ids=item.sourceIds?.length?item.sourceIds:[item.sourceId].filter(Boolean);const sources=await Promise.all(ids.map(async sourceId=>hydrateDocument(getItem(sourceId))));if(!sources.length)throw Error('Vuelve a adjuntar el manual para crear la versión completa.');input={type:'podcast',title:item.title,subject:item.subject,text:sources.map(s=>`DOCUMENTO: ${s.file?.name||s.title}\n${s.text}`).join('\n\n'),sourceIds:ids,sourceId:ids.length===1?ids[0]:null,engine:item.provider||state.settings.mode,depth:'UNDERGRADUATE'};}creatorDraft={...input,num:6,podcastJobId:null,attachments:[],editFullText:false};importVersion++;drawCreator();}catch(error){toast(error.message);}}

if(accountSession.user)import('./account-sync.js').then(m=>m.startAccountSync()).catch(error=>toast(error.message));

export const validateLibraryData=validData;

if(accountSession.user)import('./icloud.js').then(m=>m.startICloud()).catch(()=>{});

import('./framework-background.js').then(m=>m.startFrameworkBackground());
